    .-on-color,
    .-condensed,
    .-without-background,
    .-without-border,
    [aria-pressed="true"],
    :disabled,
    [aria-disabled="true"],
    :last-child
  ) {
  border-inline-end-color: color-mix(in srgb, currentColor 35%, transparent);
}

