/**
 * @component button-set
 * @summary A non-wrapping, flush row of buttons joined by 1px seams, with only its outer two corners rounded.
 * @remarks Its own chained modifiers (`-color-*`, `-size-*`, `-shape-*`, `-toggle`, `-condensed`,
 *   `-without-background`, `-without-border`, `-display-block`) set a default for every child
 *   `.pfx-button` that doesn't carry its own modifier in that same category — a button's own
 *   modifier class always wins over the group's default. `-icon-*` is always per-button; it's
 *   never read from the group. Deprecated button aliases (`-ghost`, `-color-primary-inverse`)
 *   aren't supported as group-level modifiers — use their canonical replacements
 *   (`-color-tertiary`, `-on-color`) instead. Each join shows a single 1px seam in the buttons'
 *   own border color (solid fills, whose border matches the fill, tint it with the label color).
 *   `-without-seam` is group-only: it hides that seam so the buttons read as
 *   one continuous control.
 * @modifier -without-seam — Hide the 1px seam between buttons.
 * @modifier -color-primary — Default every unmodified child to the primary color.
 * @modifier -color-secondary — Default every unmodified child to the secondary color.
 * @modifier -color-tertiary — Default every unmodified child to the tertiary (text-style) color.
 * @modifier -color-danger — Default every unmodified child to the destructive color.
 * @modifier -color-success — Default every unmodified child to the success color.
 * @modifier -color-ai — Default every unmodified child to the AI gradient treatment.
 * @modifier -color-ai-secondary — Default every unmodified child to the lower-emphasis AI treatment.
 * @modifier -on-color — Default every unmodified child for placement on a coloured surface.
 * @modifier -size-sm — Default every unmodified child to small.
 * @modifier -size-md — (default) medium size.
 * @modifier -size-lg — Default every unmodified child to large.
 * @modifier -shape-circle — Default every unmodified child to a round icon button.
 * @modifier -shape-square — Default every unmodified child to a square icon button.
 * @modifier -toggle — Default every unmodified child to the pressed-state toggle treatment.
 * @modifier -condensed — Default every unmodified child to tighter padding.
 * @modifier -without-background — Default every unmodified child to no fill.
 * @modifier -without-border — Default every unmodified child to no border.
 * @modifier -display-block — Lay every unmodified child out full-width.
 * @a11y Use a labelled group for related actions; when buttons represent a toggle choice, expose each state with aria-pressed. Give icon-only buttons an accessible name.
 * @structure
 * .pfx-button-set {
 *   @component button:one-or-more {}
 * }
 * @example
 * ```html
 * <div class="pfx-button-set -size-sm -toggle">
 *   <button class="pfx-button">Left</button>
 *   <button class="pfx-button">Right</button>
 * </div>
 * ```
 * @example -automatica11y -nocard
 * ```html
 * <div class="pfx-button-set -toggle" role="group" aria-label="Calendar view" data-a11y-root>
 *   <button class="pfx-button" aria-pressed="true" data-a11y-trigger>Week</button>
 *   <button class="pfx-button" aria-pressed="false">Month</button>
 * </div>
 * <div class="pfx-button-set -color-primary" role="group" aria-label="Primary actions">
 *   <button class="pfx-button">Save</button><button class="pfx-button" disabled>Send</button>
 * </div>
 * <div class="pfx-button-set -color-secondary" role="group" aria-label="Secondary actions">
 *   <button class="pfx-button">Save</button><button class="pfx-button" aria-disabled="true">Send</button>
 * </div>
 * <div class="pfx-button-set -color-tertiary" role="group" aria-label="Tertiary actions">
 *   <button class="pfx-button">Save</button><button class="pfx-button" disabled>Send</button>
 * </div>
 * <div class="pfx-button-set -color-danger" role="group" aria-label="Destructive actions">
 *   <button class="pfx-button">Delete</button><button class="pfx-button" disabled>Remove</button>
 * </div>
 * <div class="pfx-button-set -color-success" role="group" aria-label="Success actions">
 *   <button class="pfx-button">Approve</button><button class="pfx-button" disabled>Accept</button>
 * </div>
 * <div class="pfx-button-set -color-ai" role="group" aria-label="AI actions">
 *   <button class="pfx-button">Draft</button><button class="pfx-button" disabled>Rewrite</button>
 * </div>
 * <div class="pfx-button-set -color-ai-secondary" role="group" aria-label="Secondary AI actions">
 *   <button class="pfx-button">Draft</button><button class="pfx-button" disabled>Rewrite</button>
 * </div>
 * <div style="background: var(--instui-color-background-brand)">
 *   <div class="pfx-button-set -on-color" role="group" aria-label="On-color actions">
 *     <button class="pfx-button">Save</button><button class="pfx-button" disabled>Send</button>
 *   </div>
 * </div>
 * <div class="pfx-button-set -size-sm" role="group" aria-label="Small actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -size-md" role="group" aria-label="Medium actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -size-lg" role="group" aria-label="Large actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -shape-circle" role="group" aria-label="Circular actions">
 *   <button class="pfx-button -icon-plus" aria-label="Add"></button><button class="pfx-button -icon-x" aria-label="Remove"></button>
 * </div>
 * <div class="pfx-button-set -shape-square" role="group" aria-label="Square actions">
 *   <button class="pfx-button -icon-plus" aria-label="Add"></button><button class="pfx-button -icon-x" aria-label="Remove"></button>
 * </div>
 * <div class="pfx-button-set -condensed" role="group" aria-label="Condensed actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -without-background" role="group" aria-label="Unfilled actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -without-border" role="group" aria-label="Borderless actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -display-block" role="group" aria-label="Full-width actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * ```
 * ### Per-button override
 * ```html
 * <div class="pfx-button-set -color-secondary">
 *   <button class="pfx-button -icon-x">Cancel</button>
 *   <button class="pfx-button -color-primary -icon-checkmark">Confirm</button>
 * </div>
 * ```
 * ### Flush (no seams)
 * ```html
 * <div class="pfx-button-set -without-seam">
 *   <button class="pfx-button">Day</button>
 *   <button class="pfx-button">Week</button>
 *   <button class="pfx-button">Month</button>
 * </div>
 * ```
 * ### Split action
 * Put `-shape-square` on only the icon-only button to keep it compact beside a
 * normal text action. Its width follows the button height, including the group's
 * size default; it isn't a fraction of the text button's width. Give the icon-only
 * button an accessible name. This example shows layout only: wire the trigger
 * to a real menu and manage its expanded state and focus in your application.
 * ```html
 * <div class="pfx-button-set -color-primary" role="group" aria-label="Save actions">
 *   <button class="pfx-button" type="button">Save changes</button>
 *   <button class="pfx-button -shape-square -icon-chevron-down" type="button" aria-label="More save actions"></button>
 * </div>
 * ```
 * @related button — The child control this wraps.
 */
.pfx-button-set {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  flex-wrap: nowrap;
  gap: 0;
}

.pfx-button-set > .pfx-button {
  flex-shrink: 0;
  border-radius: 0;
}

/* Collapses the doubled border at each join to a single 1px seam in the button's border color. */
.pfx-button-set:is(:not(.-color-ai-secondary), .-without-seam) > .pfx-button:not(:first-child) {
  border-inline-start: 0;
}

/* AI-secondary's gradient frame sits outside the border box, so its seam comes from a 1px gap. */
.pfx-button-set.-color-ai-secondary:not(.-without-seam) {
  gap: var(--instui-border-width-sm);
}

/* Overlaps neighbors so no seam (or subpixel antialiasing line) shows. */
.pfx-button-set.-without-seam > .pfx-button:not(:first-child) {
  margin-inline-start: calc(-1 * var(--instui-border-width-sm));
}

.pfx-button-set.-without-seam > .pfx-button:not(:last-child) {
  border-inline-end-width: 0;
}

.pfx-button-set > .pfx-button:first-child {
  border-start-start-radius: var(--instui-component-base-button-border-radius);
  border-end-start-radius: var(--instui-component-base-button-border-radius);
}

.pfx-button-set > .pfx-button:last-child {
  border-start-end-radius: var(--instui-component-base-button-border-radius);
  border-end-end-radius: var(--instui-component-base-button-border-radius);
}

.pfx-button-set.-color-primary > .pfx-button:not([class*="-color-"]) {
  background: var(--instui-color-background-interactive-action-primary-base);
  color: var(--instui-color-text-interactive-action-primary-base);
  border-color: var(--instui-color-stroke-interactive-action-primary-base);
}

.pfx-button-set.-color-primary > .pfx-button:not([class*="-color-"]):hover {
  background: var(--instui-color-background-interactive-action-primary-hover);
  border-color: var(--instui-color-stroke-interactive-action-primary-hover);
}

.pfx-button-set.-color-primary > .pfx-button:not([class*="-color-"]):active {
  background: var(--instui-color-background-interactive-action-primary-active);
  border-color: var(--instui-color-stroke-interactive-action-primary-active);
}

.pfx-button-set.-color-primary > .pfx-button:not([class*="-color-"]):disabled,
.pfx-button-set.-color-primary > .pfx-button:not([class*="-color-"])[aria-disabled="true"] {
  background: var(--instui-component-base-button-primary-disabled-background-color);
  border-color: var(--instui-component-base-button-primary-disabled-border-color);
  color: var(--instui-component-base-button-primary-color);
}

.pfx-button-set.-color-secondary > .pfx-button:not([class*="-color-"]) {
  background: var(--instui-component-base-button-secondary-background);
  color: var(--instui-component-base-button-secondary-color);
  border-color: var(--instui-component-base-button-secondary-border-color);
}

.pfx-button-set.-color-secondary > .pfx-button:not([class*="-color-"]):hover {
  background: var(--instui-component-base-button-secondary-hover-background);
  border-color: var(--instui-component-base-button-secondary-hover-border-color);
  color: var(--instui-component-base-button-secondary-hover-text-color);
}

.pfx-button-set.-color-secondary > .pfx-button:not([class*="-color-"]):active {
  background: var(--instui-component-base-button-secondary-active-background);
  border-color: var(--instui-component-base-button-secondary-active-border-color);
  color: var(--instui-component-base-button-secondary-active-text-color);
}

.pfx-button-set.-color-secondary > .pfx-button:not([class*="-color-"]):disabled,
.pfx-button-set.-color-secondary > .pfx-button:not([class*="-color-"])[aria-disabled="true"] {
  background: var(--instui-component-base-button-secondary-disabled-background-color);
  border-color: var(--instui-component-base-button-secondary-disabled-border-color);
  color: var(--instui-component-base-button-secondary-disabled-text-color);
}

.pfx-button-set.-color-danger > .pfx-button:not([class*="-color-"]) {
  background: var(--instui-color-background-interactive-action-destructive-base);
  color: var(--instui-color-text-interactive-action-status-base);
}

.pfx-button-set.-color-danger > .pfx-button:not([class*="-color-"]):hover {
  background: var(--instui-color-background-interactive-action-destructive-hover);
}

.pfx-button-set.-color-danger > .pfx-button:not([class*="-color-"]):active {
  background: var(--instui-color-background-interactive-action-destructive-active);
}

.pfx-button-set.-color-success > .pfx-button:not([class*="-color-"]) {
  background: var(--instui-color-background-interactive-action-success-base);
  color: var(--instui-color-text-interactive-action-status-base);
}

.pfx-button-set.-color-success > .pfx-button:not([class*="-color-"]):hover {
  background: var(--instui-color-background-interactive-action-success-hover);
}

.pfx-button-set.-color-tertiary > .pfx-button:not([class*="-color-"]) {
  background: transparent;
  color: var(--instui-component-base-button-primary-ghost-color);
  border-color: var(--instui-component-base-button-primary-ghost-border-color);
}

.pfx-button-set.-color-tertiary > .pfx-button:not([class*="-color-"]):hover {
  background: var(--instui-component-base-button-primary-ghost-hover-background);
  border-color: var(--instui-component-base-button-tertiary-hover-border-color);
  color: var(--instui-component-base-button-tertiary-hover-text-color);
}

.pfx-button-set.-color-tertiary > .pfx-button:not([class*="-color-"]):active {
  background: var(--instui-component-base-button-primary-ghost-active-background);
  border-color: var(--instui-component-base-button-tertiary-active-border-color);
  color: var(--instui-component-base-button-tertiary-active-text-color);
}

.pfx-button-set.-color-tertiary > .pfx-button:not([class*="-color-"]):disabled,
.pfx-button-set.-color-tertiary > .pfx-button:not([class*="-color-"])[aria-disabled="true"] {
  background: transparent;
  border-color: var(--instui-component-base-button-tertiary-disabled-border-color);
  color: var(--instui-component-base-button-tertiary-disabled-text-color);
}

/*
 * AI gradients duplicate button.css's own -color-ai/-color-ai-secondary declarations so a plain
 * child button can inherit them from the group; a button's own -color-ai(-secondary) class still
 * wins via button.css's higher-specificity same-element rule.
 */
/* fallow-ignore-next-line code-duplication -- group-owned AI defaults must match standalone core buttons without adding child classes */
.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"]) {
  color: var(--instui-color-text-interactive-action-ai-base);
  border-color: transparent;
  background:
    linear-gradient(
        to bottom,
        var(--instui-color-background-interactive-action-ai-top-gradient-base) 0%,
        var(--instui-color-background-interactive-action-ai-bottom-gradient-base) 100%
      )
      padding-box,
    linear-gradient(
        to bottom,
        var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
        var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
      )
      border-box;
}

/* fallow-ignore-next-line code-duplication -- AI hover tokens intentionally match the core button contract */
.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"]):hover {
  color: var(--instui-color-text-interactive-action-ai-hover);
  background:
    linear-gradient(
        to bottom,
        var(--instui-color-background-interactive-action-ai-top-gradient-hover) 0%,
        var(--instui-color-background-interactive-action-ai-bottom-gradient-hover) 100%
      )
      padding-box,
    linear-gradient(
        to bottom,
        var(--instui-color-stroke-interactive-action-ai-top-gradient-hover) 0%,
        var(--instui-color-stroke-interactive-action-ai-bottom-gradient-hover) 100%
      )
      border-box;
}

/* fallow-ignore-next-line code-duplication -- AI active tokens intentionally match the core button contract */
.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"]):active {
  color: var(--instui-color-text-interactive-action-ai-active);
  background:
    linear-gradient(
        to bottom,
        var(--instui-color-background-interactive-action-ai-top-gradient-active) 0%,
        var(--instui-color-background-interactive-action-ai-bottom-gradient-active) 100%
      )
      padding-box,
    linear-gradient(
        to bottom,
        var(--instui-color-stroke-interactive-action-ai-top-gradient-active) 0%,
        var(--instui-color-stroke-interactive-action-ai-bottom-gradient-active) 100%
      )
      border-box;
}

.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"]):disabled,
.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"])[aria-disabled="true"] {
  color: var(--instui-component-base-button-ai-disabled-text-color);
  border-color: var(--instui-component-base-button-ai-disabled-border-color);
  background: var(--instui-component-base-button-ai-disabled-background-color);
}

.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"])::before {
  background: var(--instui-color-text-interactive-action-ai-base);
}

.pfx-button-set.-color-ai
  > .pfx-button:not([class*="-color-"]):is([class^="-icon-"], [class*=" -icon-"])::before {
  background: currentColor;
}

.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"]):disabled::before,
.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"])[aria-disabled="true"]::before {
  background: var(--instui-component-icon-action-ai-disabled-color);
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]) {
  position: relative;
  border-color: transparent;
  background: linear-gradient(
    to bottom,
    var(--instui-color-text-interactive-action-ai-secondary-top-gradient-base) 0%,
    var(--instui-color-text-interactive-action-ai-secondary-bottom-gradient-base) 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}

/* fallow-ignore-next-line code-duplication -- the group-owned secondary AI border uses the core button's masked-gradient technique */
.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"])::after {
  content: "";
  position: absolute;
  inset: calc(-1 * var(--instui-border-width-md));
  border-radius: inherit;
  padding: var(--instui-border-width-sm);
  background: linear-gradient(
    to bottom,
    var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
    var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
  );
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):hover,
.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):active {
  -webkit-background-clip: border-box;
  background-clip: border-box;
  color: var(--instui-color-text-interactive-action-ai-secondary-top-gradient-base);
  -webkit-text-fill-color: currentColor;
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):hover {
  background: linear-gradient(
    to bottom,
    var(--instui-color-background-interactive-action-ai-secondary-hover-top-gradient) 0%,
    var(--instui-color-background-interactive-action-ai-secondary-hover-bottom-gradient) 100%
  );
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):active {
  background: linear-gradient(
    to bottom,
    var(--instui-color-background-interactive-action-ai-secondary-active-top-gradient) 0%,
    var(--instui-color-background-interactive-action-ai-secondary-active-bottom-gradient) 100%
  );
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):disabled,
.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"])[aria-disabled="true"] {
  background: transparent;
  border-color: var(--instui-component-base-button-ai-disabled-border-color);
  color: var(--instui-component-base-button-ai-disabled-text-color);
  -webkit-text-fill-color: currentColor;
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"])::before {
  background: linear-gradient(
    to bottom,
    var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
    var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
  );
}

.pfx-button-set.-color-ai-secondary
  > .pfx-button:not([class*="-color-"]):is([class^="-icon-"], [class*=" -icon-"])::before {
  background: linear-gradient(
    to bottom,
    var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
    var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
  );
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):disabled::before,
.pfx-button-set.-color-ai-secondary
  > .pfx-button:not([class*="-color-"])[aria-disabled="true"]::before {
  background: var(--instui-component-icon-action-ai-disabled-color);
}

/* Bare -on-color defaults to the primary-on-color treatment, matching button.css. */
.pfx-button-set.-on-color > .pfx-button:not([class*="-color-"]) {
  background: var(--instui-component-base-button-primary-inverse-background);
  border-color: var(--instui-component-base-button-primary-inverse-border-color);
