+      const measure = () => page.evaluate(() => {
+        const [main, trigger] = document.querySelectorAll("button");
+        const first = main.getBoundingClientRect();
+        const second = trigger.getBoundingClientRect();
+        const style = getComputedStyle(trigger);
+        const glyph = getComputedStyle(trigger, "::before");
+        return {
+          mainWidth: first.width, mainHeight: first.height,
+          width: second.width, height: second.height,
+          join: Math.min(Math.abs(first.right - second.left), Math.abs(second.right - first.left)),
+          seam: style.borderInlineStartWidth,
+          outerRadius: style.borderStartEndRadius,
+          innerRadius: style.borderStartStartRadius,
+          glyphWidth: glyph.width, glyphMargin: glyph.marginInlineEnd, glyphMask: glyph.maskImage,
+          align: style.alignItems, justify: style.justifyContent,
+        };
+      });
+      const initial = await measure();
+      assert.equal(initial.width, initial.height, `${dir}/${size || "default"} square`);
+      assert.equal(initial.height, initial.mainHeight, "matched heights");
+      assert.ok(initial.mainWidth > initial.width, "main stays wider");
+      assert.equal(initial.join, 0, "flush join");
+      assert.equal(initial.seam, "0px", "no doubled border");
+      assert.equal(initial.innerRadius, "0px", "square inner corners");
+      assert.notEqual(initial.outerRadius, "0px", "rounded outer corners");
+      assert.ok(parseFloat(initial.glyphWidth) > 0, "visible glyph box");
+      assert.notEqual(initial.glyphMask, "none", "glyph mask loaded");
+      assert.equal(initial.glyphMargin, "0px", "no text-only glyph margin");
+      assert.equal(initial.align, "center");
+      assert.equal(initial.justify, "center");
+      await page.keyboard.press("Tab");
+      assert.equal(await page.locator("button").first().evaluate((el) => el.matches(":focus-visible")), true);
+      await page.keyboard.press("Tab");
+      assert.equal(await page.locator("button").last().evaluate((el) => el.matches(":focus-visible")), true);
+      await page.locator("button").first().evaluate((el) => { el.textContent = "Save all pending changes"; });
+      const longer = await measure();
