function provisionBrowser(): void {
  if (!process.env.CI && process.env.DOCS_ACCESSIBILITY_INSTALL_BROWSER !== "1") return;
  const manifest = createRequire(join(componentsRoot, "package.json")).resolve(
    "automatica11y/package.json",

