        var(--instui-color-stroke-interactive-action-ai-bottom-gradient-hover) 100%
      )
      border-box;
}

/* fallow-ignore-next-line code-duplication -- AI active tokens intentionally match the core button contract */
.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"]):active {
  color: var(--instui-color-text-interactive-action-ai-active);
  background:
    linear-gradient(
        to bottom,
        var(--instui-color-background-interactive-action-ai-top-gradient-active) 0%,
        var(--instui-color-background-interactive-action-ai-bottom-gradient-active) 100%
      )
      padding-box,
    linear-gradient(
        to bottom,
        var(--instui-color-stroke-interactive-action-ai-top-gradient-active) 0%,
        var(--instui-color-stroke-interactive-action-ai-bottom-gradient-active) 100%
      )
      border-box;
}

.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"]):disabled,
.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"])[aria-disabled="true"] {
  color: var(--instui-component-base-button-ai-disabled-text-color);
  border-color: var(--instui-component-base-button-ai-disabled-border-color);
  background: var(--instui-component-base-button-ai-disabled-background-color);
}

.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"])::before {
  background: var(--instui-color-text-interactive-action-ai-base);
}

.pfx-button-set.-color-ai
  > .pfx-button:not([class*="-color-"]):is([class^="-icon-"], [class*=" -icon-"])::before {
  background: currentColor;
}

.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"]):disabled::before,
.pfx-button-set.-color-ai > .pfx-button:not([class*="-color-"])[aria-disabled="true"]::before {
  background: var(--instui-component-icon-action-ai-disabled-color);
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]) {
  position: relative;
  border-color: transparent;
  background: linear-gradient(
    to bottom,
    var(--instui-color-text-interactive-action-ai-secondary-top-gradient-base) 0%,
    var(--instui-color-text-interactive-action-ai-secondary-bottom-gradient-base) 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}

/* fallow-ignore-next-line code-duplication -- the group-owned secondary AI border uses the core button's masked-gradient technique */
.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"])::after {
  content: "";
  position: absolute;
  inset: calc(-1 * var(--instui-border-width-md));
  border-radius: inherit;
  padding: var(--instui-border-width-sm);
  background: linear-gradient(
    to bottom,
    var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
    var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
  );
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):hover,
.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):active {
  -webkit-background-clip: border-box;
  background-clip: border-box;
  color: var(--instui-color-text-interactive-action-ai-secondary-top-gradient-base);
  -webkit-text-fill-color: currentColor;
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):hover {
  background: linear-gradient(
    to bottom,
    var(--instui-color-background-interactive-action-ai-secondary-hover-top-gradient) 0%,
    var(--instui-color-background-interactive-action-ai-secondary-hover-bottom-gradient) 100%
  );
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):active {
  background: linear-gradient(
    to bottom,
    var(--instui-color-background-interactive-action-ai-secondary-active-top-gradient) 0%,
    var(--instui-color-background-interactive-action-ai-secondary-active-bottom-gradient) 100%
  );
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):disabled,
.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"])[aria-disabled="true"] {
  background: transparent;
  border-color: var(--instui-component-base-button-ai-disabled-border-color);
  color: var(--instui-component-base-button-ai-disabled-text-color);
  -webkit-text-fill-color: currentColor;
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"])::before {
  background: linear-gradient(
    to bottom,
    var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
    var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
  );
}

.pfx-button-set.-color-ai-secondary
  > .pfx-button:not([class*="-color-"]):is([class^="-icon-"], [class*=" -icon-"])::before {
  background: linear-gradient(
    to bottom,
    var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
    var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
  );
}

.pfx-button-set.-color-ai-secondary > .pfx-button:not([class*="-color-"]):disabled::before,
.pfx-button-set.-color-ai-secondary
  > .pfx-button:not([class*="-color-"])[aria-disabled="true"]::before {
  background: var(--instui-component-icon-action-ai-disabled-color);
}

/* Bare -on-color defaults to the primary-on-color treatment, matching button.css. */
.pfx-button-set.-on-color > .pfx-button:not([class*="-color-"]) {
  background: var(--instui-component-base-button-primary-inverse-background);
  border-color: var(--instui-component-base-button-primary-inverse-border-color);
  color: var(--instui-component-base-button-primary-inverse-color);
}

.pfx-button-set.-on-color > .pfx-button:not([class*="-color-"]):hover {
  background: var(--instui-component-base-button-primary-inverse-hover-background);
  border-color: var(--instui-component-base-button-primary-on-color-hover-border-color);
  color: var(--instui-component-base-button-primary-on-color-hover-text-color);
}

.pfx-button-set.-on-color > .pfx-button:not([class*="-color-"]):active {
  background: var(--instui-component-base-button-primary-inverse-active-background);
  border-color: var(--instui-component-base-button-primary-on-color-active-border-color);
  color: var(--instui-component-base-button-primary-on-color-active-text-color);
}

.pfx-button-set.-on-color > .pfx-button:not([class*="-color-"]):disabled,
.pfx-button-set.-on-color > .pfx-button:not([class*="-color-"])[aria-disabled="true"] {
  background: var(--instui-component-base-button-primary-on-color-disabled-background-color);
  border-color: var(--instui-component-base-button-primary-on-color-disabled-border-color);
  color: var(--instui-component-base-button-primary-on-color-disabled-text-color);
}

.pfx-button-set.-size-sm > .pfx-button:not([class*="-size-"]) {
  font-size: var(--instui-component-base-button-small-font-size);
  min-height: var(--instui-component-base-button-small-height);
  padding-inline: var(--instui-component-base-button-small-padding-horizontal);
}

/* fallow-ignore-next-line code-duplication -- small icon-only buttons share the shape test, not the dimensions, of larger variants */
.pfx-button-set.-size-sm
  > .pfx-button:not([class*="-size-"]):is(
    .-shape-square,
    :is([class^="-icon-"], [class*=" -icon-"]):not(:has(> *)),
    :is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content:only-child)
  ) {
  inline-size: var(--instui-component-base-button-small-height);
}

.pfx-button-set.-size-md > .pfx-button:not([class*="-size-"]) {
  font-size: var(--instui-component-base-button-medium-font-size);
  min-height: var(--instui-component-base-button-medium-height);
  padding-inline: var(--instui-component-base-button-medium-padding-horizontal);
}

/* fallow-ignore-next-line code-duplication -- medium icon-only buttons need their own size-token rule */
.pfx-button-set.-size-md
  > .pfx-button:not([class*="-size-"]):is(
    .-shape-square,
    :is([class^="-icon-"], [class*=" -icon-"]):not(:has(> *)),
    :is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content:only-child)
  ) {
  inline-size: var(--instui-component-base-button-medium-height);
}

.pfx-button-set.-size-lg > .pfx-button:not([class*="-size-"]) {
  font-size: var(--instui-component-base-button-large-font-size);
  min-height: var(--instui-component-base-button-large-height);
  padding-inline: var(--instui-component-base-button-large-padding-horizontal);
}

.pfx-button-set.-size-lg
  > .pfx-button:not([class*="-size-"]):is(
    .-shape-square,
    :is([class^="-icon-"], [class*=" -icon-"]):not(:has(> *)),
    :is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content:only-child)
  ) {
  inline-size: var(--instui-component-base-button-large-height);
}

.pfx-button-set.-shape-square > .pfx-button:not([class*="-shape-"]) {
  padding: var(--instui-spacing-space-xs);
  aspect-ratio: 1;
}

.pfx-button-set.-shape-circle > .pfx-button:not([class*="-shape-"]) {
  padding: var(--instui-spacing-space-xs);
  aspect-ratio: 1;
  border-radius: 50%;
}

.pfx-button-set.-toggle > .pfx-button:not(.-toggle)[aria-pressed="true"] {
  background: var(--instui-color-background-interactive-action-secondary-active);
  border-color: var(--instui-color-stroke-interactive-action-secondary-active);
  color: var(--instui-color-text-interactive-action-secondary-base);
}

.pfx-button-set.-condensed > .pfx-button:not(.-condensed) {
  background: transparent;
  border-color: transparent;
  min-height: 0;
  color: var(--instui-color-text-interactive-action-secondary-base);
  padding-inline: var(--instui-spacing-space-xs);
}

.pfx-button-set.-condensed > .pfx-button:not(.-condensed):hover {
  background: var(--instui-color-background-muted);
}

.pfx-button-set.-without-background > .pfx-button:not(.-without-background) {
  background: var(--instui-component-base-button-primary-ghost-background);
  color: var(--instui-component-base-button-primary-ghost-color);
  border-color: var(--instui-component-base-button-primary-ghost-border-color);
}

.pfx-button-set.-without-background > .pfx-button:not(.-without-background):hover {
  background: var(--instui-component-base-button-primary-ghost-hover-background);
}

.pfx-button-set.-without-background > .pfx-button:not(.-without-background):active {
  background: var(--instui-component-base-button-primary-ghost-active-background);
}

.pfx-button-set.-without-border > .pfx-button:not(.-without-border) {
  border-style: none;
}

.pfx-button-set.-display-block > .pfx-button:not(.-display-block) {
  display: flex;
  width: 100%;
}

/* Doubled group specificity keeps half widths above inherited icon-only sizing. */
.pfx-button-set.pfx-button-set > .pfx-button.-width-half {
  inline-size: calc(var(--instui-component-base-button-medium-height) / 2);
  aspect-ratio: auto;
  padding-inline: 0;
  gap: 0;
}

.pfx-button-set.pfx-button-set.-size-sm > .pfx-button.-width-half:not([class*="-size-"]),
.pfx-button-set.pfx-button-set > .pfx-button.-width-half.-size-sm {
  inline-size: calc(var(--instui-component-base-button-small-height) / 2);
}

.pfx-button-set.pfx-button-set.-size-md > .pfx-button.-width-half:not([class*="-size-"]),
.pfx-button-set.pfx-button-set > .pfx-button.-width-half.-size-md {
  inline-size: calc(var(--instui-component-base-button-medium-height) / 2);
}

.pfx-button-set.pfx-button-set.-size-lg > .pfx-button.-width-half:not([class*="-size-"]),
.pfx-button-set.pfx-button-set > .pfx-button.-width-half.-size-lg {
  inline-size: calc(var(--instui-component-base-button-large-height) / 2);
}

.pfx-button-set.pfx-button-set > .pfx-button.-width-half::before {
  inline-size: min(1em, 100%);
  block-size: 1em;
  margin-inline-end: 0;
}

/* Solid fills (bare, primary, danger, success) paint their border in the fill color, so tint the
   seam with the label color instead. Doubled classes outrank the group hover/active rules. */
.pfx-button-set.pfx-button-set:not(
    .-without-seam,
    .-color-secondary,
    .-color-tertiary,
    .-color-ai,
    .-color-ai-secondary,
    .-on-color,
    .-condensed,
    .-without-background,
    .-without-border
  )
  > .pfx-button:not(
    [class*="-color-"],
    .-on-color,
    .-condensed,
    .-without-background,
    .-without-border,
    [aria-pressed="true"],
    :disabled,
    [aria-disabled="true"],
    :last-child
  ),
.pfx-button-set.pfx-button-set:not(
    .-without-seam,
    .-on-color,
    .-condensed,
    .-without-background,
    .-without-border
  )
  > .pfx-button:is(.-color-primary, .-color-danger, .-color-success):not(
    .-on-color,
    .-condensed,
    .-without-background,
    .-without-border,
    [aria-pressed="true"],
    :disabled,
    [aria-disabled="true"],
    :last-child
  ) {
  border-inline-end-color: color-mix(in srgb, currentColor 35%, transparent);
}

