  expect(css).not.toContain('[class*="-icon-"]');
});

test.each([
  ["sm", "small"],
  ["md", "medium"],
  ["lg", "large"],
])("button-set -width-half follows -size-%s without overriding child sizes", (size, tokenSize) => {
  for (const prefix of ["instui-", "my-", ""]) {
    const css = buttonSetRules(prefix);
    const group = `.${prefix}button-set.${prefix}button-set`;
    expect(css).toContain(
      `${group}.-size-${size} > .${prefix}button.-width-half:not([class*="-size-"]),\n${group} > .${prefix}button.-width-half.-size-${size} {\n  inline-size: calc(var(--instui-component-base-button-${tokenSize}-height) / 2);`,
    );
    expect(css).toContain(
      `${group} > .${prefix}button.-width-half {\n  inline-size: calc(var(--instui-component-base-button-medium-height) / 2);\n  aspect-ratio: auto;\n  padding-inline: 0;\n  gap: 0;`,
    );
    expect(css).toContain(
      `${group} > .${prefix}button.-width-half::before {\n  inline-size: min(1em, 100%);`,
    );
    expect(css).not.toContain(`.${prefix}button-set.-width-half`);
  }
});

test("button-set references only real tokens per theme", () => {
