+import assert from "node:assert/strict";
+import { readFileSync, realpathSync } from "node:fs";
+import { createRequire } from "node:module";
+
+const root = "/Users/dwahl/Scripts/pantoken";
+const require = createRequire(realpathSync(`${root}/formats/components/node_modules/automatica11y/package.json`));
+const { chromium } = require("playwright-core");
+const css = [
+  "formats/css/dist/style.rebrand.light.css",
+  "formats/components/dist/base.css",
+  "formats/components/dist/button.css",
+  "formats/components/dist/utilities/icon.css",
+  "formats/components/dist/icons/chevron-down.css",
+  "formats/components/dist/icons/plus.css",
+  "plugins/pantoken/custom-components/dist/button-set.css",
+].map(path => readFileSync(`${root}/${path}`, "utf8")).join("\n");
+const browser = await chromium.launch({ channel: "chrome", headless: true });
+let cases = 0;
+try {
+  const page = await browser.newPage();
+  for (const dir of ["ltr", "rtl"]) {
+    for (const size of ["", "sm", "md", "lg"]) {
+      for (const override of ["", "sm", "md", "lg"]) {
+        for (const square of ["", "-shape-square"]) {
+          const height = { sm: 32, md: 40, lg: 48 }[override || size || "md"];
+          await page.setContent(`<html dir="${dir}"><head><style>${css}</style></head><body>
+            <div class="instui-button-set ${size ? `-size-${size}` : ""}">
+              <button class="instui-button -icon-plus" aria-label="Add"></button>
+              <button class="instui-button -icon-chevron-down -width-half ${square} ${override ? `-size-${override}` : ""}" aria-label="More actions"></button>
+            </div></body></html>`);
+          const dimensions = await page.evaluate(() => {
+            const [main, trigger] = document.querySelectorAll("button");
+            const a = main.getBoundingClientRect();
+            const b = trigger.getBoundingClientRect();
+            const glyph = getComputedStyle(trigger, "::before");
+            const style = getComputedStyle(trigger);
+            return {
+              mainWidth: a.width, mainHeight: a.height, width: b.width, height: b.height,
+              join: Math.min(Math.abs(a.right - b.left), Math.abs(b.right - a.left)),
+              glyphWidth: parseFloat(glyph.width), glyphContent: glyph.content,
+              padding: parseFloat(style.paddingInlineStart) + parseFloat(style.paddingInlineEnd),
+            };
+          });
+          const label = JSON.stringify({ dir, size, override, square, dimensions });
+          assert.equal(dimensions.width, height / 2, label);
+          assert.equal(dimensions.height, height, label);
+          assert.equal(dimensions.mainWidth, dimensions.mainHeight, label);
+          assert.equal(dimensions.join, 0, label);
+          assert.equal(dimensions.padding, 0, label);
+          assert.equal(dimensions.glyphContent, '""', label);
+          assert.ok(dimensions.glyphWidth <= dimensions.width, label);
+          await page.keyboard.press("Tab");
+          await page.keyboard.press("Tab");
+          assert.ok(await page.locator("button").last().evaluate(el => el.matches(":focus-visible")), label);
+          cases++;
+        }
+      }
+    }
+  }
+  console.log(`Passed ${cases} real-browser cases: default/sm/md/lg, child overrides, shape-square composition, RTL, focus, glyph fit, and unchanged square main action.`);
+} finally {
+  await browser.close();
+}
*** End Patch

