/**
 * @component button-set
 * @summary A non-wrapping, flush row of buttons joined by 1px seams, with only its outer two corners rounded.
 * @remarks Its own chained modifiers (`-color-*`, `-size-*`, `-shape-*`, `-toggle`, `-condensed`,
 *   `-without-background`, `-without-border`, `-display-block`) set a default for every child
 *   `.pfx-button` that doesn't carry its own modifier in that same category — a button's own
 *   modifier class always wins over the group's default. `-icon-*` is always per-button; it's
 *   never read from the group. Deprecated button aliases (`-ghost`, `-color-primary-inverse`)
 *   aren't supported as group-level modifiers — use their canonical replacements
 *   (`-color-tertiary`, `-on-color`) instead. Each join shows a single 1px seam in the buttons'
 *   own border color (solid fills, whose border matches the fill, tint it with the label color).
 *   `-without-seam` is group-only: it hides that seam so the buttons read as
 *   one continuous control.
 *   Put `-width-half` on an individual icon-only child button for a split-action
 *   trigger with half the standard square width and the full button height.
 * @modifier -without-seam — Hide the 1px seam between buttons.
 * @modifier -color-primary — Default every unmodified child to the primary color.
 * @modifier -color-secondary — Default every unmodified child to the secondary color.
 * @modifier -color-tertiary — Default every unmodified child to the tertiary (text-style) color.
 * @modifier -color-danger — Default every unmodified child to the destructive color.
 * @modifier -color-success — Default every unmodified child to the success color.
 * @modifier -color-ai — Default every unmodified child to the AI gradient treatment.
 * @modifier -color-ai-secondary — Default every unmodified child to the lower-emphasis AI treatment.
 * @modifier -on-color — Default every unmodified child for placement on a coloured surface.
 * @modifier -size-sm — Default every unmodified child to small.
 * @modifier -size-md — (default) medium size.
 * @modifier -size-lg — Default every unmodified child to large.
 * @modifier -shape-circle — Default every unmodified child to a round icon button.
 * @modifier -shape-square — Default every unmodified child to a square icon button.
 * @modifier -toggle — Default every unmodified child to the pressed-state toggle treatment.
 * @modifier -condensed — Default every unmodified child to tighter padding.
 * @modifier -without-background — Default every unmodified child to no fill.
 * @modifier -without-border — Default every unmodified child to no border.
 * @modifier -display-block — Lay every unmodified child out full-width.
 * @a11y Use a labelled group for related actions; when buttons represent a toggle choice, expose each state with aria-pressed. Give icon-only buttons an accessible name. Half-width triggers are narrow targets (16px, 20px, or 24px at the standard sizes); ensure sufficient target spacing or use a full-width square button for touch interfaces.
 * @structure
 * .pfx-button-set {
 *   @component button:one-or-more {}
 * }
 * @example
 * ```html
 * <div class="pfx-button-set -size-sm -toggle">
 *   <button class="pfx-button">Left</button>
 *   <button class="pfx-button">Right</button>
 * </div>
 * ```
 * @example -automatica11y -nocard
 * ```html
 * <div class="pfx-button-set -toggle" role="group" aria-label="Calendar view" data-a11y-root>
 *   <button class="pfx-button" aria-pressed="true" data-a11y-trigger>Week</button>
 *   <button class="pfx-button" aria-pressed="false">Month</button>
 * </div>
 * <div class="pfx-button-set -color-primary" role="group" aria-label="Primary actions">
 *   <button class="pfx-button">Save</button><button class="pfx-button" disabled>Send</button>
 * </div>
 * <div class="pfx-button-set -color-secondary" role="group" aria-label="Secondary actions">
 *   <button class="pfx-button">Save</button><button class="pfx-button" aria-disabled="true">Send</button>
 * </div>
 * <div class="pfx-button-set -color-tertiary" role="group" aria-label="Tertiary actions">
 *   <button class="pfx-button">Save</button><button class="pfx-button" disabled>Send</button>
 * </div>
 * <div class="pfx-button-set -color-danger" role="group" aria-label="Destructive actions">
 *   <button class="pfx-button">Delete</button><button class="pfx-button" disabled>Remove</button>
 * </div>
 * <div class="pfx-button-set -color-success" role="group" aria-label="Success actions">
 *   <button class="pfx-button">Approve</button><button class="pfx-button" disabled>Accept</button>
 * </div>
 * <div class="pfx-button-set -color-ai" role="group" aria-label="AI actions">
 *   <button class="pfx-button">Draft</button><button class="pfx-button" disabled>Rewrite</button>
 * </div>
 * <div class="pfx-button-set -color-ai-secondary" role="group" aria-label="Secondary AI actions">
 *   <button class="pfx-button">Draft</button><button class="pfx-button" disabled>Rewrite</button>
 * </div>
 * <div style="background: var(--instui-color-background-brand)">
 *   <div class="pfx-button-set -on-color" role="group" aria-label="On-color actions">
 *     <button class="pfx-button">Save</button><button class="pfx-button" disabled>Send</button>
 *   </div>
 * </div>
 * <div class="pfx-button-set -size-sm" role="group" aria-label="Small actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -size-md" role="group" aria-label="Medium actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -size-lg" role="group" aria-label="Large actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -shape-circle" role="group" aria-label="Circular actions">
 *   <button class="pfx-button -icon-plus" aria-label="Add"></button><button class="pfx-button -icon-x" aria-label="Remove"></button>
 * </div>
 * <div class="pfx-button-set -shape-square" role="group" aria-label="Square actions">
 *   <button class="pfx-button -icon-plus" aria-label="Add"></button><button class="pfx-button -icon-x" aria-label="Remove"></button>
 * </div>
 * <div class="pfx-button-set -condensed" role="group" aria-label="Condensed actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -without-background" role="group" aria-label="Unfilled actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -without-border" role="group" aria-label="Borderless actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -display-block" role="group" aria-label="Full-width actions">
 *   <button class="pfx-button">Day</button><button class="pfx-button">Week</button>
 * </div>
 * <div class="pfx-button-set -color-primary" role="group" aria-label="Save actions">
 *   <button class="pfx-button" type="button">Save changes</button>
 *   <button class="pfx-button -width-half -icon-chevron-down" type="button" aria-label="More save actions"></button>
 * </div>
 * ```
 * ### Per-button override
 * ```html
 * <div class="pfx-button-set -color-secondary">
 *   <button class="pfx-button -icon-x">Cancel</button>
 *   <button class="pfx-button -color-primary -icon-checkmark">Confirm</button>
 * </div>
 * ```
 * ### Flush (no seams)
 * ```html
 * <div class="pfx-button-set -without-seam">
 *   <button class="pfx-button">Day</button>
 *   <button class="pfx-button">Week</button>
 *   <button class="pfx-button">Month</button>
 * </div>
 * ```
 * ### Split action
 * Put `-width-half` on only the icon-only trigger to give it half the standard
 * square button's width, keeping the full height. The main action can have a text
 * label or be an icon-only square button. Group sizes and per-button size
 * overrides apply; the width isn't a fraction of the main action. Give the icon-only
 * button an accessible name. This example shows layout only: wire the trigger
 * to a real menu and manage its expanded state and focus in your application.
 * ```html
 * <div class="pfx-button-set -color-primary" role="group" aria-label="Save actions">
 *   <button class="pfx-button" type="button">Save changes</button>
 *   <button class="pfx-button -width-half -icon-chevron-down" type="button" aria-label="More save actions"></button>
 * </div>
 * <div class="pfx-button-set -size-md" role="group" aria-label="Add actions">
 *   <button class="pfx-button -shape-square -icon-plus" type="button" aria-label="Add"></button>
 *   <button class="pfx-button -width-half -icon-chevron-down" type="button" aria-label="More add actions"></button>
 * </div>
 * ```
 * @related button — The child control this wraps.
 */
.pfx-button-set {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  flex-wrap: nowrap;
  gap: 0;
}

.pfx-button-set > .pfx-button {
  flex-shrink: 0;
  border-radius: 0;
}

/* Collapses the doubled border at each join to a single 1px seam in the button's border color. */
.pfx-button-set:is(:not(.-color-ai-secondary), .-without-seam) > .pfx-button:not(:first-child) {
  border-inline-start: 0;
}

/* AI-secondary's gradient frame sits outside the border box, so its seam comes from a 1px gap. */
.pfx-button-set.-color-ai-secondary:not(.-without-seam) {
  gap: var(--instui-border-width-sm);
}

/* Overlaps neighbors so no seam (or subpixel antialiasing line) shows. */
.pfx-button-set.-without-seam > .pfx-button:not(:first-child) {
  margin-inline-start: calc(-1 * var(--instui-border-width-sm));
}

.pfx-button-set.-without-seam > .pfx-button:not(:last-child) {
  border-inline-end-width: 0;
}

.pfx-button-set > .pfx-button:first-child {
  border-start-start-radius: var(--instui-component-base-button-border-radius);
  border-end-start-radius: var(--instui-component-base-button-border-radius);
}

.pfx-button-set > .pfx-button:last-child {
  border-start-end-radius: var(--instui-component-base-button-border-radius);
  border-end-end-radius: var(--instui-component-base-button-border-radius);
}

.pfx-button-set.-color-primary > .pfx-button:not([class*="-color-"]) {
  background: var(--instui-color-background-interactive-action-primary-base);
  color: var(--instui-color-text-interactive-action-primary-base);
  border-color: var(--instui-color-stroke-interactive-action-primary-base);
}

.pfx-button-set.-color-primary > .pfx-button:not([class*="-color-"]):hover {
  background: var(--instui-color-background-interactive-action-primary-hover);
  border-color: var(--instui-color-stroke-interactive-action-primary-hover);
}

.pfx-button-set.-color-primary > .pfx-button:not([class*="-color-"]):active {
  background: var(--instui-color-background-interactive-action-primary-active);
  border-color: var(--instui-color-stroke-interactive-action-primary-active);
}

.pfx-button-set.-color-primary > .pfx-button:not([class*="-color-"]):disabled,
.pfx-button-set.-color-primary > .pfx-button:not([class*="-color-"])[aria-disabled="true"] {
  background: var(--instui-component-base-button-primary-disabled-background-color);
  border-color: var(--instui-component-base-button-primary-disabled-border-color);
  color: var(--instui-component-base-button-primary-color);
}

.pfx-button-set.-color-secondary > .pfx-button:not([class*="-color-"]) {
  background: var(--instui-component-base-button-secondary-background);
  color: var(--instui-component-base-button-secondary-color);
