import { expect, test } from "vite-plus/test";
import { capabilitiesOf } from "@pantoken/plugin-kit";
import { unknownReferences } from "@pantoken/utils";
import { byTheme } from "@pantoken/tokens";
import {
  agentShellRules,
  aiGradientRules,
  bannerRules,
  breakpointDeclarations,
  buttonSetRules,
  cardRules,
  customComponents,
  logoRules,
  skeletonLoaderRules,
  segmentedControlRules,
} from "../src/index.ts";

const cssOf = (plugin: ReturnType<typeof customComponents>): string => {
  const out = plugin.css?.({ tokens: [], css: "" });
  return (out && "append" in out ? (out.append as string) : "") || "";
};

test("is a css-only plugin", () => {
  expect(capabilitiesOf(customComponents())).toEqual(["css"]);
});

test("extra-small breakpoint is declared in the plugin CSS", () => {
  const declaration = breakpointDeclarations();
  expect(declaration).toContain("--instui-breakpoints-xs: 20em;");
  expect(cssOf(customComponents())).toContain(declaration);
});

test("appends by default, prepends when asked", () => {
  const appended = customComponents().css?.({ tokens: [], css: "" });
  expect(appended).toHaveProperty("append");
  const prepended = customComponents({ position: "prepend" }).css?.({ tokens: [], css: "" });
  expect(prepended).toHaveProperty("prepend");
});

test("card root uses the dedicated background, sm border-radius as mobile default, and elevation-card", () => {
  const css = cssOf(customComponents());
  expect(css).toContain("var(--instui-component-card-background-color)");
  expect(css).toContain("var(--instui-component-card-border-radius-base-sm)");
  expect(css).toContain("var(--instui-elevation-card)");
});

test("card root has overflow:hidden and flex-shrink:0", () => {
  const css = cssOf(customComponents());
  expect(css).toContain("overflow: hidden");
  expect(css).toContain("flex-shrink: 0");
});

test("responsive breakpoints step padding and border-radius at 320px and 640px", () => {
  const css = cssOf(customComponents());
  expect(css).toContain("@media (min-width: 20rem)");
  expect(css).toContain("@media (min-width: 40rem)");
  expect(css).toContain("var(--instui-component-card-padding-base-sm)");
  expect(css).toContain("var(--instui-component-card-padding-base-md)");
  expect(css).toContain("var(--instui-component-card-padding-base-lg)");
  expect(css).toContain("var(--instui-component-card-border-radius-base-md)");
  expect(css).toContain("var(--instui-component-card-border-radius-base-lg)");
});

test("container variant adds border and responsive gap/border-radius to direct children", () => {
  const css = cssOf(customComponents());
  expect(css).toContain("-variant-container");
  expect(css).toContain("var(--instui-component-card-nested-border-color)");
  expect(css).toContain("--instui-component-card-border-radius-nested-sm");
  expect(css).toContain("--instui-component-card-border-radius-nested-lg");
  expect(css).toContain(
    "var(--instui-component-shared-tokens-spacing-gap-cards-nested-containers-sm)",
  );
  expect(css).toContain(
    "var(--instui-component-shared-tokens-spacing-gap-cards-nested-containers-lg)",
  );
});

test("@scope block contains container-variant direct-child rules", () => {
  const css = cssOf(customComponents());
  expect(css).toContain("@scope (.instui-card)");
  expect(css).toMatch(/&\.-variant-container\s*>\s*:not\(\.content\)/u);
  expect(css).toMatch(/&\.-variant-container\s*>\s*\.content\s*>\s*\*/u);
});

test("every custom component appears in the plugin css output", () => {
  const css = cssOf(customComponents());
  expect(css).toContain(cardRules());
  expect(css).toContain(agentShellRules());
  expect(css).toContain(bannerRules());
  expect(css).toContain(aiGradientRules());
  expect(css).toContain(logoRules());
  expect(css).toContain(buttonSetRules());
  expect(css).toContain(skeletonLoaderRules());
  expect(css).toContain(segmentedControlRules());
});

test("segmented control uses native radio states and the three upstream sizes", () => {
  const css = segmentedControlRules();
  expect(css).toContain(".instui-segmented-control");
  expect(css).toContain("&:has(input:checked)");
  expect(css).toContain("&:has(input:focus-visible)");
  expect(css).toContain("&:has(input:disabled)");
  expect(css).toContain("0 2px 4px 2px var(--instui-color-drop-shadow-shadow-color2)");
  expect(css).toContain("0 1px 2px 0 var(--instui-color-drop-shadow-shadow-color1)");
  expect(css).toContain("--instui-drop-shadow-y-elevation3-dropshadow2");
  expect(css).toContain("--instui-drop-shadow-blur-elevation3-dropshadow1");
  expect(css).not.toContain("--instui-elevation-depth1");
  for (const size of ["sm", "md", "lg"]) {
    expect(css).toContain(`--instui-component-segmented-control-height-${size}`);
    expect(css).toContain(`--instui-component-segmented-control-font-size-${size}`);
    expect(css).toContain(`--instui-component-segmented-control-item-padding-horizontal-${size}`);
  }
  expect(css).toContain(".overflow-start");
  expect(css).toContain(".overflow-end");
  expect(segmentedControlRules("my-")).toContain(".my-segmented-control");
  expect(segmentedControlRules("")).toContain(".segmented-control {");
});

test("segmented control references only upstream or shared elevation/focus tokens", () => {
  for (const theme of ["rebrand", "canvas", "canvasHighContrast"] as const) {
    const drift = unknownReferences(segmentedControlRules(), byTheme(theme)).filter(
      (name) => !name.startsWith("--instui-elevation-") && !name.startsWith("--instui-focus-"),
    );
    expect(drift).toEqual([]);
  }
});

test("skeleton loader supports prefixing and all decorative variants", () => {
  const css = skeletonLoaderRules();
  expect(css).toContain(".instui-skeleton-loader");
  expect(css).toContain(".skeleton-row");
  expect(css).toContain("&.-type-text");
  expect(css).toContain("&.-type-avatar");
  expect(css).toContain("&.-type-image");
  expect(css).toContain("::before");
  expect(skeletonLoaderRules("my-")).toContain(".my-skeleton-loader");
  expect(skeletonLoaderRules("")).toContain(".skeleton-loader {");
});

test("skeleton text rows use size-specific heights and internal leading", () => {
  const css = skeletonLoaderRules();
  expect(css).toContain("&.-size-md");
  for (const size of ["xxs", "xs", "sm", "md", "lg", "xl", "xxl"]) {
    expect(css).toContain(`--instui-component-skeleton-loader-text-height-${size}`);
    expect(css).toContain(`--instui-component-skeleton-loader-text-padding-${size}`);
  }
  expect(css).toContain("padding-block: var(--pantoken-skeleton-padding)");
  expect(css).toContain("margin-block: var(--pantoken-skeleton-padding)");
  expect(css).not.toContain("row-gap:");
});

test("skeleton shimmer shares its phase, stops after three cycles, and respects reduced motion", () => {
  const css = skeletonLoaderRules();
  expect(css).toContain("inherits: true");
  expect(css).toContain("--instui-component-skeleton-loader-duration");
  expect(css).toContain("--instui-component-skeleton-loader-bezier");
  expect(css).toContain("cubic-bezier(var(--instui-component-skeleton-loader-bezier)) 3 forwards");
  expect(css).toContain("background-position: calc(100% - var(--pantoken-skeleton-sweep))");
  expect(css).toContain("@media (prefers-reduced-motion: reduce)");
  expect(css).toContain("animation: none");
});

test("skeleton loader references only available tokens in each theme", () => {
  for (const theme of ["rebrand", "canvas", "canvasHighContrast"] as const) {
    expect(unknownReferences(skeletonLoaderRules(), byTheme(theme))).toEqual([]);
  }
});

test("buttonSetRules emits prefixed and unprefixed selectors", () => {
  expect(buttonSetRules()).toContain(".instui-button-set");
  expect(buttonSetRules("my-")).toContain(".my-button-set");
  expect(buttonSetRules("")).toContain(".button-set {");
});

test("button-set joins show one shared 1px border that -without-seam hides", () => {
  const css = buttonSetRules("instui-");
  expect(css).toContain(".instui-button-set {");
  expect(css).toContain("gap: 0");
  expect(css).toContain("flex-wrap: nowrap");
  expect(css).not.toContain("flex-wrap: wrap");
  expect(css).not.toContain("box-shadow");
  expect(css).toContain(".instui-button-set > .instui-button {");
  expect(css).toContain("border-radius: 0");
  expect(css).toContain(
    ".instui-button-set:is(:not(.-color-ai-secondary), .-without-seam) > .instui-button:not(:first-child) {\n  border-inline-start: 0;",
  );
  expect(css).toContain(
    ".instui-button-set.-color-ai-secondary:not(.-without-seam) {\n  gap: var(--instui-border-width-sm);",
  );
  expect(css).toContain("margin-inline-start: calc(-1 * var(--instui-border-width-sm))");
  expect(css).toContain(
    ".instui-button-set.-without-seam > .instui-button:not(:last-child) {\n  border-inline-end-width: 0;",
  );
  expect(css).toContain(".instui-button-set > .instui-button:first-child");
  expect(css).toContain(
    "border-start-start-radius: var(--instui-component-base-button-border-radius)",
  );
  expect(css).toContain(".instui-button-set > .instui-button:last-child");
  expect(css).toContain(
    "border-start-end-radius: var(--instui-component-base-button-border-radius)",
  );
});

test("button-set cascades -size-sm and -toggle defaults to unmodified children", () => {
  const css = buttonSetRules("instui-");
  expect(css).toContain('.instui-button-set.-size-sm > .instui-button:not([class*="-size-"])');
  expect(css).toContain("var(--instui-component-base-button-small-height)");
  expect(css).toContain(
    '.instui-button-set.-toggle > .instui-button:not(.-toggle)[aria-pressed="true"]',
  );
  expect(css).toContain("var(--instui-color-background-interactive-action-secondary-active)");
});

test("button-set cascades -color-secondary to unmodified children only", () => {
  const css = buttonSetRules("instui-");
  expect(css).toContain(
    '.instui-button-set.-color-secondary > .instui-button:not([class*="-color-"])',
  );
  expect(css).toContain("var(--instui-component-base-button-secondary-background)");
  // A button's own -color-* class is excluded from every cascaded rule, so button.css's
  // higher-specificity same-element rule for `.instui-button.-color-primary` still applies.
  expect(css).not.toContain(".instui-button-set.-color-secondary > .instui-button.-color-primary");
});

test.each([
  ["sm", "small"],
  ["md", "medium"],
  ["lg", "large"],
])("button-set -size-%s preserves a per-button square trigger", (size, tokenSize) => {
  for (const prefix of ["instui-", "my-", ""]) {
    const css = buttonSetRules(prefix);
    const selector = `.${prefix}button-set.-size-${size}`;
    const squareRule = css
      .split("}")
      .find(
        (rule) =>
          rule.includes(selector) &&
          rule.includes(".-shape-square") &&
          rule.includes("inline-size:"),
      );
    expect(squareRule).toBeDefined();
    expect(squareRule).toContain(`> .${prefix}button:not([class*="-size-"])`);
    expect(squareRule).toContain(
      `inline-size: var(--instui-component-base-button-${tokenSize}-height);`,
    );
    expect(css).toContain(
      `${selector} > .${prefix}button:not([class*="-size-"]) {\n  font-size: var(--instui-component-base-button-${tokenSize}-font-size);\n  min-height: var(--instui-component-base-button-${tokenSize}-height);`,
    );
  }
});

test("button-set never cascades -icon-* from the group", () => {
  const css = buttonSetRules("instui-");
  expect(css).not.toMatch(/\.instui-button-set\.-icon-/u);
  expect(css).toContain(':is([class^="-icon-"], [class*=" -icon-"])');
  expect(css).not.toContain('[class*="-icon-"]');
});

test.each([
  ["sm", "small"],
  ["md", "medium"],
  ["lg", "large"],
])("button-set -width-half follows -size-%s without overriding child sizes", (size, tokenSize) => {
  for (const prefix of ["instui-", "my-", ""]) {
    const css = buttonSetRules(prefix);
    const group = `.${prefix}button-set.${prefix}button-set`;
    const button = `.${prefix}button.${prefix}button.${prefix}button.-width-half`;
    expect(css).toContain(
      `${group}.-size-${size}\n  > ${button}:not([class*="-size-"]),\n${group} > ${button}.-size-${size} {\n  inline-size: calc(var(--instui-component-base-button-${tokenSize}-height) / 2);`,
    );
    expect(css).toContain(
      `${group} > ${button} {\n  inline-size: calc(var(--instui-component-base-button-medium-height) / 2);\n  aspect-ratio: auto;\n  padding-inline: 0;\n  gap: 0;`,
    );
    expect(css).toContain(`${group} > ${button}::before {\n  inline-size: min(1em, 100%);`);
    expect(css).not.toContain(`.${prefix}button-set.-width-half`);
  }
});

test("button-set references only real tokens per theme", () => {
  for (const theme of ["rebrand", "canvas", "canvasHighContrast"] as const) {
    const drift = unknownReferences(buttonSetRules("instui-"), byTheme(theme));
