test("banner defaults buttons to -size-sm unless a size modifier is present", () => {
  const css = bannerRules("instui-");
  expect(css).toMatch(
    />\s*\.instui-button:not\(\[class\*="-size-"\]\),\s*>\s*\.button-group\s*>\s*\.instui-button:not\(\[class\*="-size-"\]\)\s*\{/u,
